insert into public.memes
  (id, title, image_url, image_uri, kind, tags, source, meaning, origin, example, created_at)
values
  ('explained-18', 'Boardroom Suggestion', 'https://explained.meme/assets/explained-18-boardroom-suggestion.jpg', 'https://explained.meme/assets/explained-18-boardroom-suggestion.jpg', 'meme', array['explained','editorial-reference','workplace','corporate logic','rejection','webcomic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/boardroom-suggestion', 'Shows a sensible proposal being punished while safer or worse ideas receive approval, usually mocking corporate decision-making.', 'Hejibits webcomic (2012)', 'More meetings. More dashboards. Fix the actual problem — thrown out of the window.', now()),
  ('explained-19', 'Gru''s Plan', 'https://explained.meme/assets/explained-19-gru-s-plan.jpg', 'https://explained.meme/assets/explained-19-gru-s-plan.jpg', 'meme', array['explained','editorial-reference','plan failure','presentation','realisation','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/grus-plan', 'A multi-panel plan looks sensible until the presenter reaches a step revealing that the plan defeats itself.', 'Despicable Me / Reddit (2018)', 'Automate the report. Spend six hours fixing the automation. Repeat every week. Wait.', now()),
  ('explained-20', 'I Am Once Again Asking', 'https://explained.meme/assets/explained-20-i-am-once-again-asking.jpg', 'https://explained.meme/assets/explained-20-i-am-once-again-asking.jpg', 'meme', array['explained','editorial-reference','request','politics','repetition','reaction'], 'explained_editorial_reference:https://time.com/5779804/bernie-sanders-memes/', 'A repeated request, appeal or demand framed as something the speaker has already asked for before.', 'Bernie Sanders campaign video / social media (2020)', 'I am once again asking you to name the final file final-final-v7.', now()),
  ('explained-22', 'Doge', 'https://explained.meme/assets/explained-22-doge.jpg', 'https://explained.meme/assets/explained-22-doge.jpg', 'meme', array['explained','editorial-reference','dog','Shiba Inu','inner monologue','image macro'], 'explained_editorial_reference:https://knowyourmeme.com/memes/doge', 'Uses a Shiba Inu photograph with fragmented inner-monologue captions such as “such,” “very” and “wow.”', 'Kabosu photograph / Tumblr (2010)', 'Such deadline. Very spreadsheet. Much panic. Wow.', now()),
  ('explained-23', 'Cheems', 'https://explained.meme/assets/explained-23-cheems.jpg', 'https://explained.meme/assets/explained-23-cheems.jpg', 'meme', array['explained','editorial-reference','dog','Shiba Inu','misspelling','Dogelore'], 'explained_editorial_reference:https://knowyourmeme.com/memes/cheems', 'A Shiba Inu character associated with deliberately misspelled words, especially inserting extra M sounds, and awkward or self-deprecating behaviour.', 'Balltze Instagram photograph / Dogelore (2019)', 'I will finish the documemt tommorrow.', now()),
  ('explained-25', 'UNO Draw 25', 'https://explained.meme/assets/explained-25-uno-draw-25.jpg', 'https://explained.meme/assets/explained-25-uno-draw-25.jpg', 'meme', array['explained','editorial-reference','dilemma','refusal','cards','object labelling'], 'explained_editorial_reference:https://knowyourmeme.com/memes/draw-25', 'Presents a simple action versus drawing 25 cards, implying that the person would rather accept an absurd penalty than do the action.', 'Twitter (2020)', 'Reply to the email now or draw 25.', now()),
  ('explained-26', 'Running Away Balloon', 'https://explained.meme/assets/explained-26-running-away-balloon.jpg', 'https://explained.meme/assets/explained-26-running-away-balloon.jpg', 'meme', array['explained','editorial-reference','obstacle','distraction','object labelling','webcomic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/running-away-balloon', 'Shows somebody reaching for a goal while another force pulls them away, illustrating a limitation, distraction or obstacle.', 'Superelmer comic / Facebook (2017)', 'Me reaching for eight hours of sleep while one more episode pulls me back.', now()),
  ('explained-27', 'Always Has Been', 'https://explained.meme/assets/explained-27-always-has-been.jpg', 'https://explained.meme/assets/explained-27-always-has-been.jpg', 'meme', array['explained','editorial-reference','revelation','catchphrase','astronauts','exploitable'], 'explained_editorial_reference:https://knowyourmeme.com/memes/wait-its-all-ohio-always-has-been', 'A discovery is immediately confirmed by someone who already knew the truth, often with a dark or absurd threat.', '4chan / social media (2018)', 'Wait, the meeting could have been an email? Always has been.', now()),
  ('explained-29', 'They''re the Same Picture', 'https://explained.meme/assets/explained-29-they-re-the-same-picture.jpg', 'https://explained.meme/assets/explained-29-they-re-the-same-picture.jpg', 'meme', array['explained','editorial-reference','comparison','equivalence','television','reaction'], 'explained_editorial_reference:https://knowyourmeme.com/memes/theyre-the-same-picture', 'Declares two supposedly different choices, products or ideas effectively identical.', 'The Office / social media (2018)', 'Corporate asks you to compare unnecessary meeting and unnecessary call. They''re the same picture.', now()),
  ('explained-30', 'Left Exit 12 Off Ramp', 'https://explained.meme/assets/explained-30-left-exit-12-off-ramp.jpg', 'https://explained.meme/assets/explained-30-left-exit-12-off-ramp.jpg', 'meme', array['explained','editorial-reference','choice','distraction','driving','object labelling'], 'explained_editorial_reference:https://knowyourmeme.com/memes/left-exit-12-off-ramp', 'Shows someone abruptly abandoning the sensible route for a tempting or irrational alternative.', 'YouTube / Reddit (2017)', 'Finish the priority task; suddenly reorganise the entire desktop.', now()),
  ('explained-31', 'Bike Fall', 'https://explained.meme/assets/explained-31-bike-fall.jpg', 'https://explained.meme/assets/explained-31-bike-fall.jpg', 'meme', array['explained','editorial-reference','self-sabotage','blame','bicycle','comic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/bike-fall', 'Blames another person or thing for a problem the subject clearly caused themselves.', 'Bâton Roue webcomic by Corentin Penloup / Tumblr-era circulation (2011)', 'Ignore every warning; system fails; blame the software.', now()),
  ('explained-32', 'Clown Makeup', 'https://explained.meme/assets/explained-32-clown-makeup.jpg', 'https://explained.meme/assets/explained-32-clown-makeup.jpg', 'meme', array['explained','editorial-reference','escalation','self-delusion','clown','progression'], 'explained_editorial_reference:https://knowyourmeme.com/memes/clown-makeup', 'Shows a person progressing through increasingly foolish decisions until they have fully made a clown of themselves.', 'Facebook (May 2019) / Twitter spread (June 2019)', 'Say yes to one meeting; accept six more; wonder why no work gets done.', now()),
  ('explained-33', 'Epic Handshake', 'https://explained.meme/assets/explained-33-epic-handshake.jpg', 'https://explained.meme/assets/explained-33-epic-handshake.jpg', 'meme', array['explained','editorial-reference','agreement','comparison','handshake','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/epic-handshake', 'Highlights common ground, a shared trait or agreement between two otherwise different groups.', 'Predator footage / YouTube (2007)', 'Morning people and night owls: both hate 8 a.m. meetings.', now()),
  ('explained-34', 'Sweating Jordan Peele', 'https://explained.meme/assets/explained-34-sweating-jordan-peele.jpg', 'https://explained.meme/assets/explained-34-sweating-jordan-peele.jpg', 'meme', array['explained','editorial-reference','pressure','nervousness','reaction','comedy'], 'explained_editorial_reference:https://knowyourmeme.com/memes/sweating-jordan-peele', 'Expresses extreme pressure, nervousness or panic when facing a difficult choice or discovery.', 'Key & Peele / reaction GIFs (2013)', 'When the client says, ‘Can you share your screen?’', now()),
  ('explained-35', 'Vince McMahon Reaction', 'https://explained.meme/assets/explained-35-vince-mcmahon-reaction.jpg', 'https://explained.meme/assets/explained-35-vince-mcmahon-reaction.jpg', 'meme', array['explained','editorial-reference','escalation','excitement','reaction','wrestling'], 'explained_editorial_reference:https://knowyourmeme.com/memes/vince-mcmahon-reaction', 'Escalates through several stages of excitement, approval or amazement.', 'YouTube / WWE footage (2013)', 'No meeting; email cancelled; deadline extended; Friday off.', now()),
  ('explained-36', 'Roll Safe', 'https://explained.meme/assets/explained-36-roll-safe.jpg', 'https://explained.meme/assets/explained-36-roll-safe.jpg', 'meme', array['explained','editorial-reference','bad logic','cleverness','reaction','television'], 'explained_editorial_reference:https://knowyourmeme.com/memes/roll-safe', 'Presents flawed reasoning as though it were a clever solution.', 'The Hood Documentary / Twitter (2016)', 'You cannot miss a deadline if you never set one.', now()),
  ('explained-37', 'Arthur Fist', 'https://explained.meme/assets/explained-37-arthur-fist.jpg', 'https://explained.meme/assets/explained-37-arthur-fist.jpg', 'meme', array['explained','editorial-reference','anger','frustration','reaction','cartoon'], 'explained_editorial_reference:https://knowyourmeme.com/memes/arthurs-fist', 'Represents controlled anger, frustration or the effort to remain calm.', 'Arthur / Twitter (2016)', 'When someone replies all to say ‘thanks.’', now()),
  ('explained-38', 'Confused Nick Young', 'https://explained.meme/assets/explained-38-confused-nick-young.jpg', 'https://explained.meme/assets/explained-38-confused-nick-young.jpg', 'meme', array['explained','editorial-reference','confusion','disbelief','reaction','interview'], 'explained_editorial_reference:https://knowyourmeme.com/memes/confused-nick-young', 'Reacts to a baffling, contradictory or nonsensical statement.', 'Through the Lens / YouTube (2014)', 'The project is urgent, but nobody has approved it.', now()),
  ('explained-39', 'Blinking White Guy', 'https://explained.meme/assets/explained-39-blinking-white-guy.jpg', 'https://explained.meme/assets/explained-39-blinking-white-guy.jpg', 'meme', array['explained','editorial-reference','disbelief','surprise','reaction','GIF'], 'explained_editorial_reference:https://knowyourmeme.com/memes/blinking-white-guy', 'Shows disbelief or surprise after hearing something absurd or unexpected.', 'NeoGAF / Giant Bomb footage (2015)', 'You want the report today, but the data arrives tomorrow?', now()),
  ('explained-40', 'Michael Scott No God Please No', 'https://explained.meme/assets/explained-40-michael-scott-no-god-please-no.jpg', 'https://explained.meme/assets/explained-40-michael-scott-no-god-please-no.jpg', 'meme', array['explained','editorial-reference','rejection','dread','reaction','television'], 'explained_editorial_reference:https://knowyourmeme.com/memes/michael-scott-no-god-please-no', 'Expresses intense rejection, dread or horror at something happening again.', 'The Office, “Frame Toby” (2008)', 'Another mandatory team-building workshop? No, God, please no.', now()),
  ('explained-41', 'Oprah You Get a Car', 'https://explained.meme/assets/explained-41-oprah-you-get-a-car.jpg', 'https://explained.meme/assets/explained-41-oprah-you-get-a-car.jpg', 'meme', array['explained','editorial-reference','distribution','giveaway','reaction','television'], 'explained_editorial_reference:https://knowyourmeme.com/memes/oprah-you-get-a-car', 'Shows something being distributed freely or indiscriminately to everyone.', 'The Oprah Winfrey Show footage / YouTube (2008)', 'You get a meeting, you get a meeting, everybody gets a meeting.', now()),
  ('explained-42', 'Leonardo DiCaprio Cheers', 'https://explained.meme/assets/explained-42-leonardo-dicaprio-cheers.jpg', 'https://explained.meme/assets/explained-42-leonardo-dicaprio-cheers.jpg', 'meme', array['explained','editorial-reference','approval','toast','reaction','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/leonardo-dicaprio-cheers', 'Signals recognition, approval, congratulations or a knowing toast.', 'The Great Gatsby (2013)', 'The spreadsheet balances on the first attempt. Cheers.', now()),
  ('explained-43', 'Leonardo DiCaprio Laughing', 'https://explained.meme/assets/explained-43-leonardo-dicaprio-laughing.jpg', 'https://explained.meme/assets/explained-43-leonardo-dicaprio-laughing.jpg', 'meme', array['explained','editorial-reference','laughter','mockery','reaction','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/leonardo-dicaprio-laughing', 'Shows delighted, mocking or disbelieving laughter at another person''s claim.', 'Django Unchained footage / Tumblr (2017)', '‘It will only be a five-minute meeting.’', now()),
  ('explained-44', 'Sad Pablo Escobar', 'https://explained.meme/assets/explained-44-sad-pablo-escobar.jpg', 'https://explained.meme/assets/explained-44-sad-pablo-escobar.jpg', 'meme', array['explained','editorial-reference','waiting','loneliness','boredom','television'], 'explained_editorial_reference:https://knowyourmeme.com/memes/pablo-escobar-waiting', 'Represents lonely waiting, boredom or having nothing to do.', 'Narcos season 2 footage / social media (2016)', 'Waiting for someone to approve the final draft.', now()),
  ('explained-45', 'Waiting Skeleton', 'https://explained.meme/assets/explained-45-waiting-skeleton.jpg', 'https://explained.meme/assets/explained-45-waiting-skeleton.jpg', 'meme', array['explained','editorial-reference','waiting','delay','skeleton','reaction'], 'explained_editorial_reference:https://knowyourmeme.com/memes/waiting-for-op', 'Exaggerates how long someone has been waiting for an event, reply or result.', 'Meme Generator “Waiting for OP” image macro (2010)', 'Me waiting for the ‘quick’ software update to finish.', now()),
  ('explained-46', 'Confused Travolta', 'https://explained.meme/assets/explained-46-confused-travolta.jpg', 'https://explained.meme/assets/explained-46-confused-travolta.jpg', 'meme', array['explained','editorial-reference','confusion','searching','reaction','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/confused-travolta', 'Shows someone looking around in confusion because something or somebody is missing.', 'Pulp Fiction footage / Imgur (2015)', 'Opening the shared folder after someone says the file is definitely there.', now()),
  ('explained-47', 'Spider-Man Pointing', 'https://explained.meme/assets/explained-47-spider-man-pointing.jpg', 'https://explained.meme/assets/explained-47-spider-man-pointing.jpg', 'meme', array['explained','editorial-reference','comparison','duplication','accusation','cartoon'], 'explained_editorial_reference:https://knowyourmeme.com/memes/spider-man-pointing-at-spider-man', 'Compares two nearly identical people or groups accusing or recognising each other.', 'Spider-Man animated series / Sharenator (2011)', 'Marketing blaming Sales; Sales blaming Marketing.', now()),
  ('explained-48', 'Batman Slapping Robin', 'https://explained.meme/assets/explained-48-batman-slapping-robin.jpg', 'https://explained.meme/assets/explained-48-batman-slapping-robin.jpg', 'meme', array['explained','editorial-reference','dialogue','interruption','correction','comic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/batman-slapping-robin', 'A blunt interruption or correction delivered before the other person can finish speaking.', 'World’s Finest Comics #153 (1965) / image-macro circulation (late 2000s)', 'Robin: Let’s add another feature— Batman: Ship the current version.', now()),
  ('explained-49', 'Trollface', 'https://explained.meme/assets/explained-49-trollface.jpg', 'https://explained.meme/assets/explained-49-trollface.jpg', 'meme', array['explained','editorial-reference','trolling','character','reaction','rage comic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/trollface', 'Signals deliberate trolling, provocation or satisfaction after causing annoyance.', 'DeviantArt (2008)', 'Changes the group-chat name and waits for the notifications.', now()),
  ('explained-50', 'Grumpy Cat', 'https://explained.meme/assets/explained-50-grumpy-cat.jpg', 'https://explained.meme/assets/explained-50-grumpy-cat.jpg', 'meme', array['explained','editorial-reference','cat','displeasure','reaction','character'], 'explained_editorial_reference:https://knowyourmeme.com/memes/grumpy-cat', 'Expresses persistent displeasure, pessimism or rejection.', 'Reddit (2012)', 'Team celebration scheduled for 8 a.m. No.', now()),
  ('explained-51', 'Nyan Cat', 'https://explained.meme/assets/explained-51-nyan-cat.jpg', 'https://explained.meme/assets/explained-51-nyan-cat.jpg', 'meme', array['explained','editorial-reference','cat','pixel art','rainbow','internet classic'], 'explained_editorial_reference:https://knowyourmeme.com/memes/nyan-cat-pop-tart-cat', 'A flying pixel cat with a rainbow trail, used as a playful symbol of early internet absurdity.', 'LOL-COMICS (2011)', 'The report is late, but at least the loading animation is cheerful.', now()),
  ('explained-52', 'Keyboard Cat', 'https://explained.meme/assets/explained-52-keyboard-cat.jpg', 'https://explained.meme/assets/explained-52-keyboard-cat.jpg', 'meme', array['explained','editorial-reference','cat','failure','outro','video'], 'explained_editorial_reference:https://knowyourmeme.com/memes/keyboard-cat', 'A cat playing a keyboard, often used as a humorous outro after failure or embarrassment.', 'YouTube (2009)', 'Presentation crashes on the final slide. Play him off, Keyboard Cat.', now()),
  ('explained-53', 'Dramatic Chipmunk', 'https://explained.meme/assets/explained-53-dramatic-chipmunk.jpg', 'https://explained.meme/assets/explained-53-dramatic-chipmunk.jpg', 'meme', array['explained','editorial-reference','dramatic reveal','reaction','animal','video'], 'explained_editorial_reference:https://knowyourmeme.com/memes/dramatic-chipmunk', 'A sudden dramatic turn toward the camera that exaggerates a reveal or accusation.', 'YouTube (2007)', 'Someone mentions the missing budget line. Dramatic turn.', now()),
  ('explained-54', 'Ermahgerd', 'https://explained.meme/assets/explained-54-ermahgerd.jpg', 'https://explained.meme/assets/explained-54-ermahgerd.jpg', 'meme', array['explained','editorial-reference','excitement','character macro','books','pronunciation'], 'explained_editorial_reference:https://knowyourmeme.com/memes/ermahgerd', 'Represents overwhelming nerdy excitement using deliberately distorted pronunciation.', 'Reddit (2012)', 'Ermahgerd, the meeting was cancelled!', now()),
