  ('explained-56', 'Scumbag Steve', 'https://explained.meme/assets/explained-56-scumbag-steve.jpg', 'https://explained.meme/assets/explained-56-scumbag-steve.jpg', 'meme', array['explained','editorial-reference','selfishness','character macro','advice animal','behaviour'], 'explained_editorial_reference:https://knowyourmeme.com/memes/scumbag-steve', 'Labels inconsiderate, selfish or socially obnoxious behaviour.', 'Reddit (2011)', 'Borrows your charger; returns only the cable.', now()),
  ('explained-57', 'Condescending Wonka', 'https://explained.meme/assets/explained-57-condescending-wonka.jpg', 'https://explained.meme/assets/explained-57-condescending-wonka.jpg', 'meme', array['explained','editorial-reference','sarcasm','condescension','reaction','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/condescending-wonka-creepy-wonka', 'Pairs a patronising reaction with sarcastic disbelief about somebody''s claim.', 'Quickmeme (2010)', 'You finished one task early? Please, tell me more about productivity.', now()),
  ('explained-58', 'The Most Interesting Man in the World', 'https://explained.meme/assets/explained-58-the-most-interesting-man-in-the-world.jpg', 'https://explained.meme/assets/explained-58-the-most-interesting-man-in-the-world.jpg', 'meme', array['explained','editorial-reference','statement','advertising','character macro','catchphrase'], 'explained_editorial_reference:https://knowyourmeme.com/memes/the-most-interesting-man-in-the-world', 'Uses the structure ‘I don''t always X, but when I do, Y’ for an exaggerated personal rule.', 'Dos Equis television commercial (2007)', 'I don''t always join meetings, but when I do, they could have been emails.', now()),
  ('explained-59', 'First World Problems', 'https://explained.meme/assets/explained-59-first-world-problems.jpg', 'https://explained.meme/assets/explained-59-first-world-problems.jpg', 'meme', array['explained','editorial-reference','minor problem','privilege','character macro','complaint'], 'explained_editorial_reference:https://knowyourmeme.com/memes/first-world-problems', 'Mocks minor inconveniences experienced from a position of comfort or privilege.', 'Unknown / image-macro culture (2011)', 'The Wi-Fi reaches the sofa but not the garden chair.', now()),
  ('explained-60', 'Salt Bae', 'https://explained.meme/assets/explained-60-salt-bae.jpg', 'https://explained.meme/assets/explained-60-salt-bae.jpg', 'meme', array['explained','editorial-reference','flair','finishing touch','reaction','video'], 'explained_editorial_reference:https://knowyourmeme.com/memes/salt-bae', 'Shows someone adding a final touch with excessive flair or theatrical confidence.', 'Twitter (2017)', 'Adds one emoji to the quarterly report. Salt Bae.', now()),
  ('explained-61', 'Kermit Sipping Tea', 'https://explained.meme/assets/explained-61-kermit-sipping-tea.jpg', 'https://explained.meme/assets/explained-61-kermit-sipping-tea.jpg', 'meme', array['explained','editorial-reference','commentary','gossip','reaction','advertising'], 'explained_editorial_reference:https://knowyourmeme.com/memes/kermit-sipping-tea', 'Makes a pointed observation while pretending it is none of the speaker''s business.', 'Lipton “Be More Tea” advertisement / Instagram (2014)', 'Somebody deleted the backup, but that''s none of my business.', now()),
  ('explained-62', 'Evil Kermit', 'https://explained.meme/assets/explained-62-evil-kermit.jpg', 'https://explained.meme/assets/explained-62-evil-kermit.jpg', 'meme', array['explained','editorial-reference','temptation','inner conflict','dialogue','film'], 'explained_editorial_reference:https://knowyourmeme.com/memes/evil-kermit', 'Shows an internal struggle where a bad inner voice encourages temptation or irresponsible behaviour.', 'Twitter (2016)', 'Me: save the document. Evil me: close it and trust autosave.', now()),
  ('explained-63', 'Sad Keanu', 'https://explained.meme/assets/explained-63-sad-keanu.jpg', 'https://explained.meme/assets/explained-63-sad-keanu.jpg', 'meme', array['explained','editorial-reference','sadness','loneliness','reaction','celebrity'], 'explained_editorial_reference:https://knowyourmeme.com/memes/sad-keanu', 'Represents loneliness, sadness or quietly eating alone.', 'Reddit (2010)', 'When everyone is working from home except you.', now()),
  ('explained-64', 'Side-Eyeing Chloe', 'https://explained.meme/assets/explained-64-side-eyeing-chloe.jpg', 'https://explained.meme/assets/explained-64-side-eyeing-chloe.jpg', 'meme', array['explained','editorial-reference','suspicion','awkwardness','reaction','video'], 'explained_editorial_reference:https://knowyourmeme.com/memes/side-eyeing-chloe', 'A suspicious or uncomfortable side-eye used when something sounds strange or unconvincing.', 'YouTube footage / Tumblr (2013)', 'Manager: this reorganisation will simplify everything. Chloe side-eye.', now()),
  ('explained-65', 'Kombucha Girl', 'https://explained.meme/assets/explained-65-kombucha-girl.jpg', 'https://explained.meme/assets/explained-65-kombucha-girl.jpg', 'meme', array['explained','editorial-reference','evaluation','reaction','TikTok','mixed feelings'], 'explained_editorial_reference:https://knowyourmeme.com/memes/kombucha-girl', 'Shows a rapid shift between dislike and tentative approval while evaluating something.', 'TikTok video by Brittany Broski (August 2019)', 'A four-day workweek? At first unsure… actually, yes.', now()),
  ('explained-66', 'Confused Math Lady', 'https://explained.meme/assets/explained-66-confused-math-lady.jpg', 'https://explained.meme/assets/explained-66-confused-math-lady.jpg', 'meme', array['explained','editorial-reference','confusion','calculation','reaction','television'], 'explained_editorial_reference:https://knowyourmeme.com/memes/confused-math-lady', 'Visualises intense confusion or mental calculation in response to something difficult to understand.', 'Senhora do Destino footage / UKMix (2013)', 'Trying to understand how five small tasks became forty hours of work.', now()),
  ('explained-67', 'Crying Jordan', 'https://explained.meme/assets/explained-67-crying-jordan.jpg', 'https://explained.meme/assets/explained-67-crying-jordan.jpg', 'meme', array['explained','editorial-reference','defeat','disappointment','reaction','sports'], 'explained_editorial_reference:https://knowyourmeme.com/memes/crying-michael-jordan', 'Places Michael Jordan''s crying face onto people or things experiencing defeat or disappointment.', 'Hall of Fame speech (2009)', 'My weekend plans after seeing Monday''s deadline.', now()),
