-- Publishes the remaining 80 reviewed Explained entries as editorial references.
-- Both image columns are populated because the database sync trigger treats image_uri as authoritative.
-- The source prefix keeps these third-party editorial references out of Screensaver.
-- This script does not grant or modify database permissions.

begin;

on conflict (id) do update set
  title = excluded.title,
  image_url = excluded.image_url,
  image_uri = excluded.image_uri,
  kind = excluded.kind,
  tags = excluded.tags,
  source = excluded.source,
  meaning = excluded.meaning,
  origin = excluded.origin,
  example = excluded.example;

do $$
begin
  if (select count(*) from public.memes where id in (
    'explained-18','explained-19','explained-20','explained-22','explained-23','explained-25','explained-26','explained-27','explained-29','explained-30','explained-31','explained-32','explained-33','explained-34','explained-35','explained-36','explained-37','explained-38','explained-39','explained-40','explained-41','explained-42','explained-43','explained-44','explained-45','explained-46','explained-47','explained-48','explained-49','explained-50','explained-51','explained-52','explained-53','explained-54','explained-55','explained-56','explained-57','explained-58','explained-59','explained-60','explained-61','explained-62','explained-63','explained-64','explained-65','explained-66','explained-67','explained-68','explained-69','explained-70','explained-71','explained-72','explained-73','explained-74','explained-75','explained-76','explained-77','explained-78','explained-79','explained-80','explained-81','explained-82','explained-83','explained-84','explained-85','explained-86','explained-87','explained-88','explained-89','explained-90','explained-91','explained-92','explained-93','explained-94','explained-95','explained-96','explained-97','explained-98','explained-99','explained-100'
  ) and image_url is not null and image_uri is not null) <> 80 then
    raise exception 'Explained remaining release incomplete; rolling back';
  end if;
end
$$;

commit;
